If I don't write the following loop to parse the data, I won't be able to process the data in the loop string. What should be the best method?


```
  function customParser (tagString:any) {
        return {
            get: function (scope:any, context:any) {
                let result:any
                try {
                    const expr=angularParser.compile(tagString)
                    result = expr(scope,context);
                }
                catch (e) {
                }
                if (result=== undefined) {
                    result = scope[context.meta.part.value];
                }
                if (!result) {

                    if (context.meta.part.value === '.'){
                        return scope
                    }
                 
                    if(context.scopeList && context.scopeList.length>0){
                        // 倒序循环
                        for(let i=context.scopeList.length-1;i>=0;i--){
                            if(context.scopeList[i][context.meta.part.value]){
                                return context.scopeList[i][context.meta.part.value]
                            }
                        }
                    }

                    return ""; 
                }
                return result;  
            }
        };
    }
```

